import heapq

def match(orders):
    trades = []

    buy_heap = []   # (-price, seq)
    sell_heap = []  # (price, seq)

    book = {}  # id -> dict(side, price, qty, seq, active)

    seq_counter = 0

    def clean_buy_heap():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell_heap():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        oid = order[1]
        side = order[2]

        if typ == 'market':
            qty = order[3]
            price = None
        else:
            price = order[3]
            qty = order[4]

        remaining = qty

        if side == 'buy':
            # match against sell_heap
            while remaining > 0:
                clean_sell_heap()
                if not sell_heap:
                    break
                sp, sseq, sid = sell_heap[0]
                sinfo = book[sid]
                if price is not None and sp > price:
                    break
                trade_qty = min(remaining, sinfo['qty'])
                trades.append([oid, sid, sp, trade_qty])
                remaining -= trade_qty
                sinfo['qty'] -= trade_qty
                if sinfo['qty'] <= 0:
                    sinfo['active'] = False
                    heapq.heappop(sell_heap)

            if typ == 'limit' and remaining > 0:
                seq_counter += 1
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'seq': seq_counter, 'active': True}
                heapq.heappush(buy_heap, (-price, seq_counter, oid))

        else:  # sell
            while remaining > 0:
                clean_buy_heap()
                if not buy_heap:
                    break
                negbp, bseq, bid = buy_heap[0]
                bp = -negbp
                binfo = book[bid]
                if price is not None and bp < price:
                    break
                trade_qty = min(remaining, binfo['qty'])
                trades.append([bid, oid, bp, trade_qty])
                remaining -= trade_qty
                binfo['qty'] -= trade_qty
                if binfo['qty'] <= 0:
                    binfo['active'] = False
                    heapq.heappop(buy_heap)

            if typ == 'limit' and remaining > 0:
                seq_counter += 1
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'seq': seq_counter, 'active': True}
                heapq.heappush(sell_heap, (price, seq_counter, oid))

    return trades

